export const translations = Object.fromEntries(["en", "sv", "fi"].map((language, index) => [
  language,
  Object.fromEntries(rows.map(([key, ...values]) => [key, values[index]]))
]));

const sourceKeys = new Map();
for (const [key, english] of Object.entries(translations.en)) {
  if (!sourceKeys.has(english.trim().replace(/\s+/g, " "))) sourceKeys.set(english.trim().replace(/\s+/g, " "), key);
}
const sourceFragments = new Map();
for (const [english, key] of sourceKeys) {
  if (english.length >= 4 && /\p{L}/u.test(english) && !english.includes("{")) {
    const normalized = english.toLocaleLowerCase("en");
    if (!sourceFragments.has(normalized)) sourceFragments.set(normalized, key);
  }
}
const fragmentPattern = sourceFragments.size
  ? new RegExp(`(?<![\\p{L}\\p{N}])(${[...sourceFragments.keys()].sort((a, b) => b.length - a.length).map(value => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})(?![\\p{L}\\p{N}])`, "giu")
  : null;
const templatePatterns = Object.entries(translations.en)
  .filter(([, message]) => message.includes("{"))
  .map(([key, message]) => {
    const escaped = message.split(/\{([\w]+)\}/g).map((part, index) => index % 2 ? "([\\s\\S]*?)" : part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("");
    return { key, names: [...message.matchAll(/\{([\w]+)\}/g)].map(([, name]) => name), regex: new RegExp(`^${escaped}$`) };
  });

export const languages = [
  { code: "en", flag: "🇬🇧", label: "EN" },
  { code: "sv", flag: "🇸🇪", label: "SV" },
  { code: "fi", flag: "🇫🇮", label: "FI" }
];

// Temporary demo allowlist. Re-enable SV/FI here after language QA.
export const ENABLED_LANGUAGES = ["en"];

export function createI18n(root = globalThis.document, storage = globalThis.localStorage) {
  const valid = code => ENABLED_LANGUAGES.includes(code);
  let language = "en";
  try {
    const stored = storage?.getItem("boost-the-grid-language");
    if (valid(stored)) language = stored;
  } catch { /* Storage may be disabled in private browsing. */ }
  const originals = new WeakMap();
  let observer;

  const t = (key, params = {}) => {
    const message = translations[language]?.[key] ?? translations.en[key] ?? "";
    return message.replace(/\{([\w]+)\}/g, (_, name) => params[name] ?? "");
  };

  const translateSource = source => {
    const normalized = source.trim().replace(/\s+/g, " ");
    if (!normalized) return source;
    const leading = source.match(/^\s*/)?.[0] ?? "";
    const trailing = source.match(/\s*$/)?.[0] ?? "";
    const preserveSpacing = value => `${leading}${value}${trailing}`;
    if (normalized === "TUNE THE GRID." || normalized === "BOOST" || normalized === "LOCALLY." || normalized.startsWith("BOOST THE GRID ·") || normalized.startsWith("BOOST THE GRID —")) return source;
    const exactKey = sourceKeys.get(normalized);
    if (exactKey) return preserveSpacing(t(exactKey));
    for (const pattern of templatePatterns) {
      const match = normalized.match(pattern.regex);
      if (match) return preserveSpacing(t(pattern.key, Object.fromEntries(pattern.names.map((name, index) => [name, translateSource(match[index + 1])] ))));
    }
    if (!fragmentPattern) return source;
    return preserveSpacing(normalized.replace(fragmentPattern, matched => {
      const key = sourceFragments.get(matched.toLocaleLowerCase("en"));
      return key ? t(key) : matched;
    }));
  };

  const translateAttribute = (element, name) => {
    const value = element.getAttribute(name);
    if (value == null || !value.trim()) return;
    let saved = originals.get(element);
    if (!saved) { saved = new Map(); originals.set(element, saved); }
    let record = saved.get(name);
    if (!record || value !== record.rendered) record = { source: value, rendered: value };
    const translated = translateSource(record.source);
    record.rendered = translated;
    saved.set(name, record);
    if (translated !== value) element.setAttribute(name, translated);
  };

  const translateNode = node => {
    if (node.nodeType === 3) {
      const value = node.data;
      if (!value.trim()) return;
      let record = originals.get(node);
      if (!record || value !== record.rendered) record = { source: value, rendered: value };
      const translated = translateSource(record.source);
      record.rendered = translated;
      originals.set(node, record);
      if (translated !== value) node.data = translated;
      return;
    }
    if (node.nodeType !== 1 && node.nodeType !== 9 && node.nodeType !== 11) return;
    if (node.nodeType === 1) {
      if (["SCRIPT", "STYLE"].includes(node.tagName) || node.closest?.("[data-no-translate]")) return;
      for (const name of ["title", "placeholder", "aria-label", "aria-description"]) translateAttribute(node, name);
    }
    for (const child of [...(node.childNodes ?? [])]) translateNode(child);
  };

  const refreshButtons = () => {
    for (const button of root?.querySelectorAll?.("[data-language-code]") ?? []) {
      const code = button.dataset.languageCode;
      const enabled = valid(code);
      const selected = code === language;
      button.disabled = !enabled;
      button.setAttribute("aria-disabled", String(!enabled));
      button.classList.toggle("active", selected);
      button.setAttribute("aria-pressed", String(selected));
    }
  };

  const setLanguage = (code, { persist = true } = {}) => {
    if (!valid(code)) return language;
    language = code;
    if (persist) {
      try { storage?.setItem("boost-the-grid-language", language); } catch { /* Keep this session's selection. */ }
    }
    if (root?.documentElement) root.documentElement.lang = language;
    refreshButtons();
    if (root) translateNode(root);
    return language;
  };

  if (root) {
    root.addEventListener?.("click", event => {
      const button = event.target?.closest?.("[data-language-code]");
      if (button) setLanguage(button.dataset.languageCode);
    });
    const Observer = root.defaultView?.MutationObserver ?? globalThis.MutationObserver;
    if (Observer && root.documentElement) {
      observer = new Observer(records => {
        for (const record of records) {
          if (record.type === "characterData") translateNode(record.target);
          for (const node of record.addedNodes ?? []) translateNode(node);
          if (record.type === "attributes") translateAttribute(record.target, record.attributeName);
        }
      });
      observer.observe(root.documentElement, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ["title", "placeholder", "aria-label", "aria-description"] });
    }
    setLanguage(language, { persist: false });
  }

  return { t, setLanguage, getLanguage: () => language, translateSource, disconnect: () => observer?.disconnect() };
}

export const i18n = globalThis.document ? createI18n() : null;
if (i18n && globalThis.window) {
  window.t = i18n.t;
  window.setLanguage = i18n.setLanguage;
}
